} catch(e) { throw new Error('AI returned invalid JSON: ' + aiRaw); }
const arrayFields = ['conditions','surgeries','drug_allergies','food_allergies','rx_meds','otc_meds','herbal_meds','immunisations','mental_history','cognitive','directives','fam_history','assistive','substance_use','pets_type','pregnancy_complications'];
const notesFields = ['cond_other','surg_other','meds_notes','admit_details','transfusion_details','imm_notes','mental_notes','mental_current','dir_notes','fam_history_notes','assistive_notes','substance_details','lifestyle_notes','obgyn_notes'];
const changedFields = {};
for (const key of Object.keys(fullUpdated)) {
  const oldVal = existing[key];
  const newVal = fullUpdated[key];
  if (arrayFields.includes(key)) {
    const oldArr = Array.isArray(oldVal) ? oldVal : [];
    const newArr = Array.isArray(newVal) ? newVal : [];
    const trulyNew = newArr.filter(item => !oldArr.includes(item));
    if (trulyNew.length > 0) changedFields[key] = [...oldArr, ...trulyNew];
  } else if (notesFields.includes(key)) {
    const oldStr = (oldVal || '').trim();
    const newStr = (newVal || '').trim();
    if (newStr && newStr !== oldStr && !oldStr.includes(newStr)) changedFields[key] = `${oldStr}\n${newStr}`.trim();
  } else {
    if (JSON.stringify(oldVal) !== JSON.stringify(newVal)) changedFields[key] = newVal;
  }
}
return [{ json: { changedFields, updatedFields: changedFields, fullName: ctx.full_name, submissionId: existing.submission_key, toolCallId: ctx.toolCallId } }];

